package com.tms.thirdparty;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.tms.common.BizException; import com.tms.common.R; import com.tms.dispatch.entity.Waybill; import com.tms.dispatch.mapper.WaybillMapper; import com.tms.order.entity.TransportOrder; import com.tms.order.mapper.TransportOrderMapper; import com.tms.tracking.entity.TrackingEvent; import com.tms.tracking.mapper.TrackingEventMapper; import lombok.Data; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@RestController @RequestMapping("/api/thirdparty") @RequiredArgsConstructor
public class ThirdPartyController {
 private final WaybillMapper waybillMapper; private final TransportOrderMapper orderMapper; private final TrackingEventMapper eventMapper;
 @PostMapping("/callback/{provider}") public R<Void> callback(@PathVariable String provider,@RequestBody CallbackReq r){Waybill w=waybillMapper.selectOne(new LambdaQueryWrapper<Waybill>().eq(Waybill::getThirdPartyNo,r.thirdPartyNo));if(w==null)throw new BizException("三方运单不存在");w.setThirdPartyStatus(r.status);TrackingEvent e=new TrackingEvent();e.setWaybillId(w.getId());e.setWaybillCode(w.getCode());e.setEventType("THIRD_PARTY");e.setDescription(r.description);e.setLng(r.lng);e.setLat(r.lat);e.setEventTime(r.eventTime==null?LocalDateTime.now():r.eventTime);e.setSource("THIRD_PARTY");eventMapper.insert(e);if("SIGNED".equals(r.status)){w.setStatus("DELIVERED");for(TransportOrder o:orderMapper.selectList(new LambdaQueryWrapper<TransportOrder>().eq(TransportOrder::getWaybillId,w.getId()))){o.setStatus("DELIVERED");o.setSigner("三方回传");o.setSignTime(LocalDateTime.now());orderMapper.updateById(o);}}waybillMapper.updateById(w);return R.ok();}
 @Data public static class CallbackReq{private String thirdPartyNo,status,description;private BigDecimal lng,lat;private LocalDateTime eventTime;}
}
